typedef enum
{
    CAN_SYNC_COMPLETE    = 1u << 0 , 
    
    CAN_SYNC_TX          = 1u << 1 , 

    CAN_SYNC_NO_ACTION   = 0       ,

}Can_Sync_Flags ; 

//---------------------------------------------------------------------------//

typedef UInt32  Can_Sync_Id  ;

typedef void *	Can_Sync_Arg ;

typedef Can_Sync_Flags	(*Can_Sync_Func)( Can_Msg *, Can_Sync_Arg );	

//---------------------------------------------------------------------------//

#define can_sync_loop(dev_id,func,arg,id,offset)    can_sync_add(dev_id,func,arg,id,offset,0xFFFFFFFF,1,0) 

